import React, { useEffect, useMemo, useState } from "react"

import Shell from "../components/layout/Shell"
import Breadcrumb from "../components/ui/Breadcrumb"
import BreakoutFilterRail, {
  DEFAULT_BREAKOUT_FILTERS,
  filterRows,
} from "../components/breakouts/FilterRail"
import ScanTable, { SCAN_TABS } from "../components/breakouts/ScanTable"
import BreakoutDetail from "../components/breakouts/DetailRail"
import LevelChart from "../components/breakouts/LevelChart"

import { getBreakouts } from "../data/breakouts"
import { getCompany } from "../data/companies"
import { generateCandles } from "../data/candles"
import { getNews } from "../data/news"

/* -------------------------------------------------------------------------- */

/**
 * Saved screens are presets over the same filter object the rail edits, so
 * picking one visibly changes the controls and the row count. They are not
 * persisted — this is a prototype, and faking storage would be worse than
 * showing honest presets.
 */
const SAVED_SCREENS = [
  {
    id: "mine",
    name: "My breakout setup",
    meta: "$1–$20 · RVOL 1.0x+",
    filters: { ...DEFAULT_BREAKOUT_FILTERS },
  },
  {
    id: "lowfloat",
    name: "Low float breakouts",
    meta: "Under $2B cap · RVOL 1.5x+",
    filters: {
      ...DEFAULT_BREAKOUT_FILTERS,
      priceMin: 1,
      priceMax: 60,
      marketCapMin: 50e6,
      rvolMin: 1.5,
    },
  },
  {
    id: "morning",
    name: "Morning breakouts",
    meta: "Premarket and opening range",
    filters: {
      ...DEFAULT_BREAKOUT_FILTERS,
      priceMin: null,
      priceMax: null,
      rvolMin: 1.0,
      marketCapMin: 50e6,
    },
  },
  {
    id: "highvol",
    name: "High volume breakouts",
    meta: "RVOL 3.0x+ · 5M+ shares",
    filters: {
      ...DEFAULT_BREAKOUT_FILTERS,
      priceMin: null,
      priceMax: null,
      rvolMin: 3.0,
      avgVolumeMin: 5e6,
    },
  },
]

/*
 * Keyed by the SCAN_TABS *value* the table emits ("newHigh"), not by its label
 * ("New highs"). Keying by label meant every tab click looked up an undefined
 * predicate and silently fell back to "show everything", so the tabs highlighted
 * but never filtered.
 */
function predicateFor(tabValue) {
  const entry = SCAN_TABS.find(t => t.value === tabValue)
  if (!entry || !entry.signal) return () => true
  return r => r.signal === entry.signal
}

const SORTERS = {
  score: (a, b) => b.score - a.score,
  changePct: (a, b) => b.changePct - a.changePct,
  volume: (a, b) => b.volume - a.volume,
  rvol: (a, b) => (b.rvol ?? -Infinity) - (a.rvol ?? -Infinity),
}

/* -------------------------------------------------------------------------- */

export default function BreakoutsPage({ location }) {
  const all = useMemo(() => getBreakouts(), [])

  const [filters, setFilters] = useState(DEFAULT_BREAKOUT_FILTERS)
  const [applied, setApplied] = useState(DEFAULT_BREAKOUT_FILTERS)
  const [activeScreen, setActiveScreen] = useState(null)
  const [tab, setTab] = useState("all")
  const [sortKey, setSortKey] = useState("score")
  const [selectedId, setSelectedId] = useState(null)
  const [timeframe, setTimeframe] = useState("1D")

  // The applied set drives the table; the draft set drives the controls, so
  // "Run breakout scan" is a real action.
  const scanned = useMemo(() => filterRows(all, applied), [all, applied])
  const draftCount = useMemo(() => filterRows(all, filters).length, [all, filters])

  const counts = useMemo(
    () => ({
      all: scanned.length,
      newHigh: scanned.filter(predicateFor("newHigh")).length,
      resistance: scanned.filter(predicateFor("resistance")).length,
      vwap: scanned.filter(predicateFor("vwap")).length,
      premarket: scanned.filter(predicateFor("premarket")).length,
    }),
    [scanned]
  )

  const rows = useMemo(() => {
    const predicate = predicateFor(tab)
    const sorter = SORTERS[sortKey] || SORTERS.score
    // Copy before sorting — never mutate the source array.
    return scanned
      .filter(predicate)
      .slice()
      .sort((a, b) => sorter(a, b) || a.id.localeCompare(b.id))
  }, [scanned, tab, sortKey])

  /*
   * Row 1 is selected by default, and the selection follows the visible list: if
   * a filter or tab removes the selected row, fall back to the new first row
   * rather than leaving the detail rail describing something off-screen.
   */
  const selected = useMemo(() => {
    if (!rows.length) return null
    const match = rows.find(r => r.id === selectedId)
    return match || rows[0]
  }, [rows, selectedId])

  useEffect(() => {
    if (selected && selected.id !== selectedId) setSelectedId(selected.id)
  }, [selected, selectedId])

  const company = selected ? getCompany(selected.symbol) : null
  const news = selected ? getNews(selected.symbol) : []

  const chartCandles = useMemo(
    () => (selected ? generateCandles(selected.symbol, timeframe) : []),
    [selected, timeframe]
  )

  function applyScreen(screen) {
    if (!screen) return
    setActiveScreen(screen.id)
    setFilters(screen.filters)
    setApplied(screen.filters)
  }

  return (
    <Shell location={location}>
      <div className="page">
        <div className="page__breadcrumb">
          <Breadcrumb items={[{ label: "Home", to: "/" }, { label: "Breakouts" }]} />
        </div>

        <div className="bkt">
          <div className="bkt__rail-left">
            <BreakoutFilterRail
              filters={filters}
              onChange={next => {
                setFilters(next)
                setActiveScreen(null)
              }}
              onRun={() => setApplied(filters)}
              onReset={() => {
                setFilters(DEFAULT_BREAKOUT_FILTERS)
                setApplied(DEFAULT_BREAKOUT_FILTERS)
                setActiveScreen(null)
              }}
              matchCount={draftCount}
              total={all.length}
              savedScreens={SAVED_SCREENS}
              activeScreen={activeScreen}
              onSelectScreen={applyScreen}
            />
          </div>

          <div className="bkt__main">
            <ScanTable
              rows={rows}
              counts={counts}
              selectedId={selected ? selected.id : null}
              onSelect={id => setSelectedId(id)}
              tab={tab}
              onTabChange={setTab}
              sortKey={sortKey}
              onSortChange={setSortKey}
            />
          </div>

          <div className="bkt__rail-right">
            <div className="bkt__sticky">
              <BreakoutDetail
                row={selected}
                company={company}
                news={news}
                timeframe={timeframe}
                onTimeframeChange={setTimeframe}
                chart={
                  selected ? (
                    <LevelChart
                      candles={chartCandles}
                      level={selected.breakoutLevel}
                      height={200}
                    />
                  ) : null
                }
              />
            </div>
          </div>
        </div>
      </div>
    </Shell>
  )
}

export const Head = () => <title>Breakouts · MarketScan</title>
