import React, { useRef } from "react"

import Panel from "../layout/Panel"
import Delta from "../ui/Delta"
import Icon from "../ui/Icon"
import Select from "../ui/Select"
import TickerMark from "../ui/TickerMark"

/**
 * ScanTable — the centre column of /breakouts: heading, tab and sort toolbar,
 * the ranked table itself, and the explainer that sits beneath it.
 *
 * The table is hand-rolled rather than the shared DataTable because this one
 * carries a selected-row concept DataTable does not model: exactly one row is
 * the subject of the right-hand detail rail, so a row is a control with a
 * selected state, not merely a clickable strip.
 *
 * Filtering and sorting happen in the PARENT — rows arrive in final display
 * order and this component renders what it is handed. Per-tab counts cannot be
 * derived from an already-filtered list, so they arrive separately as `counts`;
 * when that prop is absent the tabs show no number rather than a wrong one.
 *
 * Props:
 *   rows          array of BREAKOUTS rows, already filtered and sorted
 *   selectedId    id of the row the detail rail is showing
 *   onSelect      (id, row) => void, fired on click, Enter and Space
 *   tab           a SCAN_TABS value: "all" | "newHigh" | "resistance"
 *                 | "vwap" | "premarket"
 *   onTabChange   (value) => void
 *   sortKey       "score" | "changePct" | "volume" | "rvol"
 *   onSortChange  (value) => void
 *   counts        optional { all, newHigh, resistance, vwap, premarket }
 *
 * SSR: no window, document or storage anywhere. The only browser API touched is
 * node.focus(), and that runs inside a keydown handler.
 */

const DASH = "—"
const RVOL_HOT = 4
const COLUMN_COUNT = 9

const isNum = value => value !== null && value !== undefined && Number.isFinite(value)

function noop() {}

/** Money carries a leading $, and a true minus (U+2212) so a column aligns. */
function usd(value, digits = 2) {
  if (!isNum(value)) return DASH
  return (value < 0 ? "−$" : "$") + Math.abs(value).toFixed(digits)
}

/** Share counts read as 34.6M rather than 34,612,880 — magnitude is the point. */
function shares(value) {
  if (!isNum(value)) return DASH
  const abs = Math.abs(value)
  if (abs >= 1e9) return (value / 1e9).toFixed(2) + "B"
  if (abs >= 1e6) return (value / 1e6).toFixed(1) + "M"
  if (abs >= 1e3) return (value / 1e3).toFixed(1) + "K"
  return String(Math.round(value))
}

function multiple(value) {
  return isNum(value) ? value.toFixed(2) + "x" : DASH
}

/* -------------------------------------------------------------------------- */
/* Tabs and sorting                                                            */
/* -------------------------------------------------------------------------- */

/**
 * Exported so the parent filters against the same vocabulary the tabs emit.
 * A value defined here and a value assumed there drifting apart is the classic
 * way this pattern breaks, and `signal` names the row field each tab matches.
 */
export const SCAN_TABS = [
  { value: "all", label: "All breakouts", signal: null },
  { value: "newHigh", label: "New highs", signal: "New high" },
  { value: "resistance", label: "Resistance breaks", signal: "Resistance break" },
  { value: "vwap", label: "VWAP breaks", signal: "VWAP break" },
  { value: "premarket", label: "Premarket breakouts", signal: "Premarket break" },
]

const SORT_OPTIONS = [
  { label: "Breakout score", value: "score" },
  { label: "Change %", value: "changePct" },
  { label: "Volume", value: "volume" },
  { label: "RVOL", value: "rvol" },
]

/* -------------------------------------------------------------------------- */
/* Signals                                                                     */
/* -------------------------------------------------------------------------- */

const SIGNAL_ICONS = {
  "New high": "trendingUp",
  "Resistance break": "barChart",
  "VWAP break": "activity",
  "Premarket break": "zap",
}

/** Modifier slug for the stylesheet: "VWAP break" becomes "vwap-break". */
function slugify(text) {
  const source = String(text || "").toLowerCase()
  let out = ""
  for (let i = 0; i < source.length; i += 1) {
    const ch = source.charAt(i)
    const keep = (ch >= "a" && ch <= "z") || (ch >= "0" && ch <= "9")
    out += keep ? ch : "-"
  }
  return out
}

/*
 * The three bands the stylesheet tints, set against the scores this data
 * actually produces (20-65) rather than an assumed 0-100 spread. At the old
 * 90/80 cutoffs every one of the 24 rows fell through to "low" and two styled
 * CSS bands were dead code.
 */
const SCORE_HIGH = 60
const SCORE_MID = 45

function scoreBand(score) {
  if (!isNum(score)) return "low"
  if (score >= SCORE_HIGH) return "high"
  if (score >= SCORE_MID) return "mid"
  return "low"
}

/* -------------------------------------------------------------------------- */

function ScanTable({
  rows,
  selectedId,
  onSelect,
  tab,
  onTabChange,
  sortKey,
  onSortChange,
  counts,
}) {
  const data = Array.isArray(rows) ? rows : []
  const select = typeof onSelect === "function" ? onSelect : noop
  const changeTab = typeof onTabChange === "function" ? onTabChange : noop
  const changeSort = typeof onSortChange === "function" ? onSortChange : noop
  const tabRefs = useRef([])

  const found = SCAN_TABS.findIndex(item => item.value === tab)
  const activeTab = found === -1 ? 0 : found

  /*
   * A roving tabindex with no arrow keys would strand every inactive tab
   * outside the keyboard's reach, so the tablist moves selection itself.
   */
  function handleTabKeyDown(event) {
    const last = SCAN_TABS.length - 1
    let next = -1

    if (event.key === "ArrowRight" || event.key === "ArrowDown") {
      next = activeTab === last ? 0 : activeTab + 1
    } else if (event.key === "ArrowLeft" || event.key === "ArrowUp") {
      next = activeTab === 0 ? last : activeTab - 1
    } else if (event.key === "Home") {
      next = 0
    } else if (event.key === "End") {
      next = last
    }

    if (next === -1) return
    event.preventDefault()

    const target = SCAN_TABS[next]
    if (!target) return
    changeTab(target.value)
    const node = tabRefs.current[next]
    if (node && typeof node.focus === "function") node.focus()
  }

  function handleRowKeyDown(event, row) {
    // Only the row itself activates, so anything focusable inside it keeps
    // its own keys.
    if (event.target !== event.currentTarget) return
    if (event.key === "Enter") {
      event.preventDefault()
      select(row.id, row)
      return
    }
    if (event.key === " " || event.key === "Spacebar") {
      event.preventDefault() /* otherwise Space scrolls the page */
      select(row.id, row)
    }
  }

  function tabLabel(item) {
    const value = counts ? counts[item.value] : null
    return isNum(value) ? item.label + " (" + value + ")" : item.label
  }

  return (
    <>
      <header className="bkt__head">
        <h1 className="bkt__title">Real-time breakout</h1>
        <p className="bkt__subtitle">
          Stocks breaking key levels right now, with confirmation signals.
        </p>
      </header>

      <div className="bkt__toolbar">
        <div className="btabs" role="tablist" aria-label="Breakout signal types">
          {SCAN_TABS.map((item, index) => {
            const active = index === activeTab
            return (
              <button
                key={item.value}
                type="button"
                role="tab"
                ref={node => {
                  tabRefs.current[index] = node
                }}
                aria-selected={active}
                tabIndex={active ? 0 : -1}
                className={"btabs__tab" + (active ? " btabs__tab--active" : "")}
                onClick={() => changeTab(item.value)}
                onKeyDown={handleTabKeyDown}
              >
                {tabLabel(item)}
              </button>
            )
          })}
        </div>

        <div className="bkt__sort">
          <Select
            label="Sort by"
            value={sortKey}
            options={SORT_OPTIONS}
            onChange={event => changeSort(event.target.value)}
          />
        </div>
      </div>

      <div className="btable__wrap">
        <table className="btable" aria-label="Breakout candidates">
          <thead>
            <tr>
              <th scope="col" className="btable__head">
                #
              </th>
              <th scope="col" className="btable__head">
                Ticker
              </th>
              <th scope="col" className="btable__head btable__head--num">
                Price
              </th>
              <th scope="col" className="btable__head btable__head--num">
                Change %
              </th>
              <th scope="col" className="btable__head btable__head--num">
                Volume
              </th>
              <th scope="col" className="btable__head btable__head--num">
                RVOL
              </th>
              <th scope="col" className="btable__head btable__head--num">
                Breakout level
              </th>
              <th scope="col" className="btable__head">
                Signal
              </th>
              <th scope="col" className="btable__head btable__head--num">
                Score
              </th>
            </tr>
          </thead>

          <tbody>
            {data.length === 0 ? (
              <tr className="btable__row">
                <td className="dt__empty" colSpan={COLUMN_COUNT}>
                  No breakouts match these filters.
                </td>
              </tr>
            ) : (
              data.map((row, index) => {
                const selected = Boolean(selectedId) && row.id === selectedId
                const hot = isNum(row.rvol) && row.rvol > RVOL_HOT
                const band = scoreBand(row.score)
                const iconName = SIGNAL_ICONS[row.signal] || "activity"
                const signalSlug = slugify(row.signal)

                return (
                  <tr
                    key={row.id}
                    className={"btable__row" + (selected ? " btable__row--selected" : "")}
                    role="button"
                    tabIndex={0}
                    aria-selected={selected}
                    onClick={() => select(row.id, row)}
                    onKeyDown={event => handleRowKeyDown(event, row)}
                  >
                    <td className="btable__cell btable__rank">{index + 1}</td>

                    <td className="btable__cell">
                      <span className="btable__ticker" title={row.name}>
                        <TickerMark symbol={row.symbol} size={20} />
                        <span className="btable__symbol">{row.symbol}</span>
                      </span>
                    </td>

                    <td className="btable__cell btable__cell--num">{usd(row.price)}</td>

                    <td className="btable__cell btable__cell--num">
                      <Delta value={row.changePct} percent digits={2} />
                    </td>

                    <td className="btable__cell btable__cell--num">{shares(row.volume)}</td>

                    <td
                      className={
                        "btable__cell btable__cell--num" + (hot ? " btable__rvol--hot" : "")
                      }
                    >
                      {multiple(row.rvol)}
                    </td>

                    <td className="btable__cell btable__cell--num">{usd(row.breakoutLevel)}</td>

                    <td className="btable__cell">
                      <span className="btable__signal">
                        <span
                          className={"btable__signal-icon btable__signal-icon--" + signalSlug}
                        >
                          <Icon name={iconName} size={14} />
                        </span>
                        {row.signal}
                      </span>
                    </td>

                    <td className="btable__cell btable__cell--num">
                      <span className={"bscore bscore--" + band}>
                        {isNum(row.score) ? row.score : DASH}
                      </span>
                    </td>
                  </tr>
                )
              })
            )}
          </tbody>
        </table>
      </div>

      <Panel
        className="bkt__explainer"
        title="How breakout scanning works"
        actions={
          <button type="button" className="btn btn--secondary btn--sm">
            Learn more
          </button>
        }
      >
        <p className="bkt__explainer-text">
          The scan watches for price clearing an established level — a prior high, a resistance
          shelf, or the session VWAP — and flags the move only once price has genuinely traded
          through that level rather than merely approached it.
        </p>
        <p className="bkt__explainer-text">
          Volume confirmation matters as much as the cross itself, because a break on thin relative
          volume rarely holds, so RVOL and the six-point checklist carry real weight in the score.
        </p>
      </Panel>
    </>
  )
}

export default ScanTable
