import React from "react"
import { Link } from "gatsby"

import { Badge, Delta, Icon, SegmentedControl } from "../ui"
import { ANCHOR_DATE } from "../../data/companies"

/**
 * The /breakouts right rail: identity, session figures, the confirmation
 * checklist, the score breakdown and recent headlines for the selected row.
 *
 * Everything is READ from props. The page selects the row, looks up the company
 * and its news once, and hands the same objects to the table and to this rail —
 * so a figure here can never disagree with the row highlighted next to it.
 *
 * Null discipline: the data layer returns null rather than a nonsense number
 * (a margin on negligible revenue, a ratio with a zero denominator, an RVOL with
 * no average to divide by). Every formatter below answers an em dash for
 * anything that is not a finite number, so nothing reaches the DOM as NaN, null,
 * undefined or Infinity.
 *
 * The mini candlestick chart is NOT built here — the page passes it in as the
 * `chart` node and this file only gives it a slot.
 *
 * Pure render: no window, document or storage, so Gatsby's Node build produces
 * the same markup the browser hydrates.
 */

const DASH = "—"
const MINUS = "−"
const MIDDOT = "·"

const TIMEFRAMES = ["1D", "5D", "1M", "3M", "6M", "1Y"]

/** At least this many of the six checks before the breakout counts as confirmed. */
const CONFIRMED_AT = 4

function isNum(value) {
  return value !== null && value !== undefined && Number.isFinite(value)
}

/** Money, always with the leading dollar sign. */
function usd(value, digits = 2) {
  return isNum(value) ? "$" + value.toFixed(digits) : DASH
}

/** 70612400 -> "70.6M". Keeps a two-column stat grid narrow. */
function compact(value) {
  if (!isNum(value)) return DASH
  const abs = Math.abs(value)
  const sign = value < 0 ? MINUS : ""
  if (abs >= 1e12) return sign + (abs / 1e12).toFixed(2) + "T"
  if (abs >= 1e9) return sign + (abs / 1e9).toFixed(2) + "B"
  if (abs >= 1e6) return sign + (abs / 1e6).toFixed(1) + "M"
  if (abs >= 1e3) return sign + (abs / 1e3).toFixed(1) + "K"
  return sign + String(Math.round(abs))
}

/** Humanised money — market cap and the like. */
function money(value) {
  return isNum(value) ? "$" + compact(value) : DASH
}

/** Relative volume reads as a multiple: "4.52x". */
function multiple(value) {
  return isNum(value) ? value.toFixed(2) + "x" : DASH
}

/** A signed percentage using a true minus sign, so it lines up with <Delta>. */
function signedPct(value, digits = 2) {
  if (!isNum(value)) return DASH
  const sign = value > 0 ? "+" : value < 0 ? MINUS : ""
  return sign + Math.abs(value).toFixed(digits) + "%"
}

/** A 0-100 sub-score, or a dash. */
function scoreText(value) {
  return isNum(value) ? String(Math.round(value)) : DASH
}

/**
 * A bar width as a serialisable percentage string. Clamped into 0-100 and
 * rounded, so the style attribute reads "72%" rather than a floating-point tail,
 * and a missing score draws an empty track rather than a full one.
 */
function barWidth(value) {
  if (!isNum(value)) return "0%"
  const clamped = value < 0 ? 0 : value > 100 ? 100 : value
  return Math.round(clamped * 10) / 10 + "%"
}

/*
 * Relative time is measured against the dataset's frozen anchor close
 * (16:00 ET = 20:00 UTC on ANCHOR_DATE), never against the system clock — the
 * same derivation the dashboard uses. Reading the real clock would age every
 * headline in the demo to "4 months ago" the moment the build sat overnight.
 */
const ANCHOR_CLOSE = (() => {
  const [y, m, d] = ANCHOR_DATE.split("-").map(Number)
  return Math.floor(Date.UTC(y, m - 1, d, 20, 0, 0) / 1000)
})()

function relativeTime(timestamp) {
  if (!isNum(timestamp)) return DASH
  const seconds = ANCHOR_CLOSE - timestamp
  if (seconds < 0) return "just now"
  if (seconds < 60) return "just now"
  const minutes = Math.round(seconds / 60)
  if (minutes < 60) return minutes + "m ago"
  const hours = Math.round(minutes / 60)
  if (hours < 24) return hours + "h ago"
  return Math.round(hours / 24) + "d ago"
}

/**
 * Enrichment for a checklist row.
 *
 * The labels come from the data and are never rewritten — this only appends a
 * figure the row genuinely carries, so a reader can see WHY a check passed or
 * failed. Checks whose inputs (VWAP, RSI) are not on the row get no suffix
 * rather than an invented one.
 */
function checkDetail(label, row) {
  if (label === "Volume above 2x average" && isNum(row.rvol)) {
    return multiple(row.rvol) + " normal volume"
  }
  if (label === "Closed above breakout level" && isNum(row.breakoutLevel)) {
    return isNum(row.distancePct)
      ? signedPct(row.distancePct) + " above " + usd(row.breakoutLevel)
      : "level " + usd(row.breakoutLevel)
  }
  if (label === "EMA 9 above EMA 20" && isNum(row.changePct)) {
    return "session " + signedPct(row.changePct)
  }
  return null
}

const SUB_ROWS = [
  { key: "technical", label: "Technical" },
  { key: "fundamental", label: "Fundamental" },
  { key: "momentum", label: "Momentum" },
  { key: "news", label: "News" },
]

function Stat({ label, value }) {
  return (
    <div className="bdetail__stat">
      <span className="bdetail__stat-label">{label}</span>
      <span className="bdetail__stat-value">{value}</span>
    </div>
  )
}

export default function BreakoutDetail({
  row,
  company,
  news,
  timeframe,
  onTimeframeChange,
  chart,
}) {
  /*
   * Nothing matched the filters. The rail still renders its surface so the
   * three-column layout does not collapse, and says so in one line.
   */
  if (!row) {
    return (
      <section className="panel bdetail">
        <p className="panel__title">No selection</p>
        <p className="panel__subtitle">
          No breakout matches the current filters. Widen a range or clear a
          filter to bring rows back.
        </p>
      </section>
    )
  }

  const co = company || {}
  const items = Array.isArray(news) ? news.slice(0, 2) : []
  const checklist = Array.isArray(row.checklist) ? row.checklist : []
  const passed = checklist.reduce((n, item) => (item && item.passed ? n + 1 : n), 0)
  const confirmed = passed >= CONFIRMED_AT
  const subScores = row.subScores || {}

  return (
    <>
      {/* Identity, price and the session figures behind the row. */}
      <section className="panel bdetail">
        <div className="bdetail__head">
          <span className="bdetail__symbol">{row.symbol || DASH}</span>
          <button type="button" className="bdetail__star" aria-label="Add to watchlist">
            <Icon name="star" size={16} />
          </button>
          <button type="button" className="btn btn--primary btn--sm">
            Add to watchlist
          </button>
        </div>

        <p className="bdetail__name">{row.name || DASH}</p>

        <div className="bdetail__chips">
          <span className="bdetail__chip">{co.exchange || DASH}</span>
          <span className="bdetail__chip">{co.sector || DASH}</span>
          <span className="bdetail__chip">{co.industry || DASH}</span>
        </div>

        <div className="bdetail__price-row">
          <span className="bdetail__price">{usd(row.price)}</span>
          <Delta value={row.changePct} percent digits={2} />
        </div>

        <div className="bdetail__stats">
          <Stat label="Volume" value={compact(row.volume)} />
          <Stat label="RVOL" value={multiple(row.rvol)} />
          <Stat label="Market cap" value={money(co.marketCap)} />
          <Stat label="Float" value={compact(co.float)} />
        </div>

        <SegmentedControl
          options={TIMEFRAMES}
          value={timeframe}
          onChange={onTimeframeChange}
          ariaLabel="Select chart timeframe"
        />

        {/* The chart itself belongs to the page — this is only its slot. */}
        <div className="bdetail__chart">{chart}</div>
      </section>

      {/* Confirmation checklist. Six real comparisons, read off the same series. */}
      <section className="panel bcheck">
        <div className="bcheck__head">
          <h3 className="panel__title">Real-time breakout</h3>
          <Badge tone={confirmed ? "bullish" : "neutral"}>
            {confirmed ? "Confirmed" : "Unconfirmed"}
          </Badge>
        </div>

        <ul className="bcheck__list">
          {checklist.map((item, index) => {
            const label = item && item.label ? item.label : DASH
            const met = Boolean(item && item.passed)
            const detail = item ? checkDetail(label, row) : null
            const text = detail ? label + " " + MIDDOT + " " + detail : label
            return (
              <li
                key={label + "-" + index}
                className={met ? "bcheck__item bcheck__item--met" : "bcheck__item"}
                /*
                 * The glyph and the colour both say "met", so the state is also
                 * spelled out here for anyone reading with a screen reader or
                 * unable to tell the two tones apart.
                 */
                aria-label={text + " " + MIDDOT + (met ? " met" : " not met")}
              >
                <span className="bcheck__mark" aria-hidden="true">
                  {met ? "✓" : "–"}
                </span>
                <span className="bcheck__text">{text}</span>
              </li>
            )
          })}
        </ul>
      </section>

      {/* Score and its four weighted inputs. */}
      <div
        className="panel bscore-block"
        role="group"
        aria-label={
          "Breakout score " + scoreText(row.score) + " out of 100"
        }
      >
        <span className="bscore-block__value">{scoreText(row.score)}</span>
        <span className="bscore-block__total">/ 100</span>

        <span className="bscore-block__track" aria-hidden="true">
          <span className="bscore-block__fill" style={{ width: barWidth(row.score) }} />
        </span>

        <div className="bscore-block__subs">
          {SUB_ROWS.map(sub => {
            const value = subScores[sub.key]
            return (
              <div className="bsub" key={sub.key}>
                <span className="bsub__label">{sub.label}</span>
                <span className="bsub__track" aria-hidden="true">
                  <span className="bsub__fill" style={{ width: barWidth(value) }} />
                </span>
                <span className="bsub__value">{scoreText(value)}</span>
              </div>
            )
          })}
        </div>
      </div>

      {/* Two most recent headlines for the symbol. */}
      <section className="panel bnews">
        <h3 className="panel__title">Recent news</h3>

        {items.length === 0 ? (
          <p className="panel__subtitle">No recent headlines for this symbol.</p>
        ) : (
          items.map((item, index) => (
            <article className="bnews__item" key={item && item.id ? item.id : index}>
              <p className="bnews__headline">{item && item.headline ? item.headline : DASH}</p>
              <p className="bnews__meta">
                {(item && item.source ? item.source : DASH) +
                  " " +
                  MIDDOT +
                  " " +
                  relativeTime(item ? item.timestamp : null)}
              </p>
            </article>
          ))
        )}

        <Link className="btn btn--ghost btn--sm" to="/news/">
          View all
          <Icon name="arrowUpRight" size={14} className="btn__icon" />
        </Link>
      </section>
    </>
  )
}
